  var full=new ProjectileEventLedger();full.Bind(sim);for(int i=0;i<64;i++){for(int j=0;j<4;j++)full.Advance(.25);C(full.TryOnset(new EntityId(100+i,1),0,true,out _),"bounded ledger fill active");}for(int j=0;j<4;j++)full.Advance(.25);C(!full.TryOnset(new(999,1),0,true,out _)&&full.LedgerDrops==1&&full.UsedVictims==64,"full ledger rejects never evicts");full.ClearPresentation();full.EndEligibleRender();full.Advance(.01);C(full.UsedVictims==0,"inactive expired ledger retires");
  var parent=new Node3D();AddChild(parent);var realLedger=new ProjectileEventLedger();realLedger.Bind(sim);bool hit=false;ProjectileTransition first=default;
